{
  "name": "@guard22/opencode-status-signals",
  "version": "0.3.4",
  "description": "Visual status signals for OpenCode sessions with in-app theme mapping.",
  "type": "module",
  "exports": {
    ".": "./src/tui.js",
    "./tui": "./src/tui.js"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "check": "node --check src/tui.js",
    "package:check": "npm pack --dry-run"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "themes",
    "session",
    "status"
  ],
  "author": "guard22",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/guard22/opencode-status-signals.git"
  },
  "homepage": "https://github.com/guard22/opencode-status-signals#readme",
  "bugs": {
    "url": "https://github.com/guard22/opencode-status-signals/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=18",
    "opencode": "^1.3.0"
  }
}
